@page "/dashboard"
@using sv_c68b11da8f8a421993eff02a988d88ca.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 28rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock items:
            <span class="badge fs-6 @BadgeClass">@AlertService.LatestLowStockCount</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds while this page is open.
        </p>
    </div>
</div>

@code {
    private string BadgeClass =>
        AlertService.LatestLowStockCount switch
        {
            > 10 => "bg-danger",
            > 5 => "bg-warning text-dark",
            > 0 => "bg-info text-dark",
            _ => "bg-success"
        };

    protected override void OnInitialized()
    {
        // Start polling — first subscriber spins up the timer.
        AlertService.Subscribe();
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private Task HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private async Task HandleWarehouseChanged()
    {
        // Immediately refresh data for the new warehouse.
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        AlertService.LatestLowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.Unsubscribe();
    }
}

